import React, { useState, useEffect } from "react";
import AchievementsPanel from "./AchievementsPanel";

export default function AdminDashboard({ reports, token, setMsg, admin }) {
  const [ngos, setNgos] = useState(null);
  const [events, setEvents] = useState(null);
  const [eventStats, setEventStats] = useState(null);
  const [mostActiveNgo, setMostActiveNgo] = useState(null);

  // ------------------ SIMPLE PROFILE BOX ------------------
  const ProfileBox = () => (
    <div className="bg-white shadow-md rounded-xl p-5 w-full mb-6">
      <h2 className="text-xl font-semibold mb-2">Profile</h2>
      <p><strong>Email:</strong> {admin?.email || "N/A"}</p>
      <p><strong>Role:</strong> {admin?.role || "Admin"}</p>
    </div>
  );

  // ------------------ UI ------------------
  return (
    <div className="min-h-screen w-full flex flex-col items-center bg-gray-100 py-10">
      <div className="w-[90%] max-w-5xl bg-white shadow-xl rounded-2xl p-8">

        {/* Dashboard Title */}
        <h1 className="text-3xl font-bold mb-6">Admin Dashboard</h1>

        {/* Profile Box under title */}
        <ProfileBox />

        {/* Spaced Components */}
        <div className="mb-10">
          <AchievementsPanel />
        </div>

        {/* Buttons Section (kept original functions) */}
        <div className="flex gap-4 mb-10">
          <button
            onClick={() => setNgos("loading")}
            className="px-5 py-2 bg-blue-600 text-white rounded-lg shadow"
          >
            Load NGOs
          </button>
          <button
            onClick={() => setEvents("loading")}
            className="px-5 py-2 bg-green-600 text-white rounded-lg shadow"
          >
            Load Events
          </button>
          <button
            onClick={() => setEventStats("loading")}
            className="px-5 py-2 bg-purple-600 text-white rounded-lg shadow"
          >
            Load Event Stats
          </button>
        </div>

        {/* MOST ACTIVE NGO CARD */}
        {mostActiveNgo && (
          <div className="bg-blue-50 p-5 rounded-xl shadow mb-10 w-full max-w-md">
            <h3 className="font-semibold text-lg mb-1">Most Active NGO</h3>
            <p className="text-sm">{mostActiveNgo.name}</p>
          </div>
        )}

        {/* Loaded Data */}
        <div className="space-y-6">
          {ngos && <div className="bg-gray-50 p-5 rounded-xl shadow">NGOs Loaded</div>}
          {events && <div className="bg-gray-50 p-5 rounded-xl shadow">Events Loaded</div>}
          {eventStats && <div className="bg-gray-50 p-5 rounded-xl shadow">Event Stats Loaded</div>}
        </div>

      </div>
    </div>
  );
}
